def _seed_roles() -> None:
    """Reference data the app cannot run without. Content is NOT seeded here (see `python -m app.cli seed`)."""
    import uuid

    from app.core.permissions import PERMISSIONS, ROLE_GRANTS

    perm_t = sa.table("permissions", sa.column("id", sa.Uuid), sa.column("code", sa.String), sa.column("description", sa.String))
    role_t = sa.table("roles", sa.column("id", sa.Uuid), sa.column("name", sa.String), sa.column("description", sa.String))
    link_t = sa.table("role_permissions", sa.column("role_id", sa.Uuid), sa.column("permission_id", sa.Uuid))
    perm_ids = {code: uuid.uuid4() for code in PERMISSIONS}
    op.bulk_insert(perm_t, [{"id": perm_ids[c], "code": c, "description": d} for c, d in PERMISSIONS.items()])
    links = []
    roles = []
    for name, (desc, codes) in ROLE_GRANTS.items():
        rid = uuid.uuid4()
        roles.append({"id": rid, "name": name, "description": desc})
        links += [{"role_id": rid, "permission_id": perm_ids[c]} for c in codes]
    op.bulk_insert(role_t, roles)
    op.bulk_insert(link_t, links)


